        for j in range(len(dist)):
            if dist[i][j] < 1000000000 and dist[i][j] > far:
                far = dist[i][j]
        total += far
    return total


def floyd_warshall(weights: list[list[int]]) -> list[list[int]]:

    n: int = len(weights)
    dist: list[list[int]] = []
    for i in range(n):
        row: list[int] = []
        for j in range(n):
            row.append(weights[i][j])
        dist.append(row)
    for k in range(n):
        for i in range(n):
            dik: int = dist[i][k]
            if dik >= 1000000000:
                continue
            for j in range(n):
                alt: int = dik + dist[k][j]
                if alt < dist[i][j]:
                    dist[i][j] = alt
    return dist

